import{_ as s,c as o,o as t,aA as a}from"./chunks/framework.C7A9pmXE.js";const m=JSON.parse('{"title":"MPM processes","description":"","frontmatter":{},"headers":[],"relativePath":"interface/mpmprocess.md","filePath":"interface/mpmprocess.md","lastUpdated":null}'),c={name:"interface/mpmprocess.md"};function r(i,e,p,n,l,d){return t(),o("div",null,e[0]||(e[0]=[a('<h1 id="MPM-processes" tabindex="-1">MPM processes <a class="header-anchor" href="#MPM-processes" aria-label="Permalink to &quot;MPM processes {#MPM-processes}&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Note</p><p>This package provides an explicit MPM solver.</p></div><p>We classify MPM processes based on stress update schemes. Generally, the stress update schemes include:</p><ul><li><p><code>USL</code></p></li><li><p><code>USF</code></p></li><li><p><code>MUSL</code></p></li><li><p><code>AFFINE</code></p></li></ul><p>Here, <code>AFFINE</code><sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> is an exception; it does not represent a stress update scheme, but since we have only implemented one stress update scheme for <code>AFFINE</code>, similar to <code>USF</code>, it is also an option.</p><p>This implementation is located under the <code>/src/solvers/</code> path, you can see some files like <code>**_MUSL.jl</code>. We just need to rearrange/modifiy the kernel functions, super easy! 🎸</p><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>He, K. Y., Liang, W., Yin, Z. Y., &amp; Jin, Y. F. (2023). An efficient material point method framework based on the affine matrix. Computers and Geotechnics, 163, 105712. <a href="https://doi.org/10.1016/j.compgeo.2023.105712" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.compgeo.2023.105712</a> <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',8)]))}const h=s(c,[["render",r]]);export{m as __pageData,h as default};
